SELECT CASE WHEN d.budget >= 3413000 THEN 'high' WHEN d.budget >= 655000 THEN 'mid' ELSE 'low' END AS budget_bucket, MIN(e.salary) AS min_salary, SUM(CASE WHEN e.job_title = 'Designer' THEN 1 ELSE 0 END) AS designer_count FROM employees e JOIN departments d ON e.dept_id = d.id WHERE e.salary < 144000 GROUP BY CASE WHEN d.budget >= 3413000 THEN 'high' WHEN d.budget >= 655000 THEN 'mid' ELSE 'low' END HAVING SUM(CASE WHEN e.job_title = 'Designer' THEN 1 ELSE 0 END) > 63 ORDER BY min_salary DESC
